cd /app && python3 - <<'EOF'
import re, glob, datetime, collections, json

files = sorted(glob.glob('/app/logs/*.log'))
date_sev = collections.defaultdict(collections.Counter)

for f in files:
    d = f.split('/')[-1].split('_')[0]
    for line in open(f):
        m = re.match(r'^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2} \[(\w+)\]', line)
        if m and m.group(1) in ('ERROR','WARNING','INFO'):
            date_sev[d][m.group(1)] += 1

ref = datetime.date(2025,8,12)

def total_in(lo, hi):
    tot = collections.Counter()
    for d,c in date_sev.items():
        dd = datetime.date.fromisoformat(d)
        if lo <= dd <= hi:
            tot.update(c)
    return tot

def fmt(c): return {k:c.get(k,0) for k in ['ERROR','WARNING','INFO']}

periods = {
 'today': (datetime.date(2025,8,12), datetime.date(2025,8,12)),
 'last_7_days': (datetime.date(2025,8,6), ref),
 'last_30_days': (datetime.date(2025,7,14), ref),
 'month_to_date': (datetime.date(2025,8,1), ref),
}
results = {}
for name,(lo,hi) in periods.items():
    c = total_in(lo,hi)
    results[name]=fmt(c)
    print(name, fmt(c), "total lines:", sum(c.values()))

tot = collections.Counter()
for c in date_sev.values(): tot.update(c)
results['total']=fmt(tot)
print('total', fmt(tot), "total lines:", sum(tot.values()))

# cross-check: per-file vs per-day consistency, and per-source breakdown for today
for f in files:
    if f.split('/')[-1].startswith('2025-08-12'):
        c=collections.Counter()
        for line in open(f):
            m=re.match(r'^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2} \[(\w+)\]', line)
            c[m.group(1)]+=1
        print(f.split('/')[-1], dict(c))

out = ["period,severity,count"]
for name in ['today','last_7_days','last_30_days','month_to_date','total']:
    for sev in ['ERROR','WARNING','INFO']:
        out.append(f"{name},{sev},{results[name][sev]}")
open('/app/summary.csv','w').write("\n".join(out)+"\n")
print("\n".join(out))
EOF

